mapper.select:
select a.id, a.sub_bill_no, a.bill_id, a.bill_no, a.bill_cycle, a.bill_date,
       a.contract_id, ct.contact_no, ct.contract_name,
       a.customer_id, cu.name as customer_name,
       a.supplier_id, s.name as supplier_name,
       a.supplier_account_id, a.usage_count,
       a.total_tokens, a.total_sell_amount, a.total_cost_amount, a.total_gross_profit,
       b.bill_status, a.creator, a.create_time, a.update_time
from crm_contract_bill_sub a
left join crm_contract_bill b on b.id = a.bill_id
left join crm_contract ct on ct.id = a.contract_id
left join crm_customer cu on cu.id = a.customer_id
left join crm_supplier s on s.id = a.supplier_id

     and a.bill_id = #{billId}
     and a.bill_no like concat('%', #{billNo}, '%')
     and a.sub_bill_no like concat('%', #{subBillNo}, '%')
     and a.bill_cycle = #{billCycle}
     and a.contract_id = #{contractId}
     and ct.contact_no like concat('%', #{contactNo}, '%')
     and a.customer_id = #{customerId}
     and a.supplier_id = #{supplierId}

        and a.bill_date >= #{params.beginDate}


        and a.bill_date <= #{params.endDate}


        and a.supplier_id in

            #{scopeSupplierId}



order by a.bill_cycle desc, a.contract_id, a.bill_date
